<template><view class="page"><text class="title">{{categoryName||'找一本想听的书'}}</text><view class="search"><input v-model="query" maxlength="100" placeholder="输入书名，如：三体" @confirm="search" @input="suggest"/><button :disabled="busy" @click="search">搜索</button></view><view v-if="suggestions.length" class="suggestions"><view v-for="item in suggestions" :key="item.id" @click="chooseSuggestion(item.title)">{{item.title}}</view></view><view class="filters"><view><button v-for="item in sortOptions" :key="item.value" :class="{active:sort===item.value}" @click="setSort(item.value)">{{item.label}}</button></view><view><button v-for="item in payOptions" :key="item.value" :class="{active:payType===item.value}" @click="setPay(item.value)">{{item.label}}</button></view></view><text class="hint">{{error||('公开专辑共 '+total+' 个 · 第 '+page+' 页')}}</text><view v-for="book in books" :key="book.id" class="book" @click="open(book.id)"><image :src="book.coverUrl" mode="aspectFill"/><view><text class="name"><template v-if="book.titleParts?.length"><text v-for="(part,i) in book.titleParts" :key="i" :class="{match:part.match}">{{part.text}}</text></template><template v-else>{{book.albumTitle}}</template></text><text class="hint">{{book.payType==='0101'?'免费内容':'付费内容 · 试听范围以详情为准'}} · {{book.includeTrackCount}} 集</text></view></view><view class="pager"><button :disabled="busy||page===1" @click="previous">上一页</button><button :disabled="busy||page*12>=total" @click="next">下一页</button></view><button class="secondary" @click="home">返回首页</button></view></template>
<script setup lang="ts">
import {ref,onUnmounted} from 'vue';
import {onLoad} from '@dcloudio/uni-app';
import {listeningRequest} from '../../api/listening';
const query=ref(''),page=ref(1),total=ref(0),books=ref<any[]>([]),busy=ref(false),error=ref(''),category=ref(0),categoryName=ref('');
const sort=ref('relevance'),payType=ref(''),suggestions=ref<any[]>([]);
const sortOptions=[{value:'relevance',label:'相关度'},{value:'popular',label:'最多收听'},{value:'newest',label:'最新专辑'}];
const payOptions=[{value:'',label:'全部内容'},{value:'0101',label:'免费'},{value:'0102',label:'会员'},{value:'0103',label:'付费'}];
let timer:ReturnType<typeof setTimeout>|undefined,suggestVersion=0,loadVersion=0;
async function load(){const version=++loadVersion;busy.value=true;error.value='';try{const data=await listeningRequest('/api/content/albums?q='+encodeURIComponent(query.value)+'&page='+page.value+'&size=12&sort='+sort.value+'&payType='+payType.value+(category.value?'&category3='+category.value:''));if(version===loadVersion){books.value=data.records;total.value=data.total}}catch(e:any){if(version===loadVersion)error.value=e.message}finally{if(version===loadVersion)busy.value=false}}
function search(){suggestVersion++;suggestions.value=[];page.value=1;load()}
function suggest(){if(timer)clearTimeout(timer);const version=++suggestVersion;const text=query.value.trim();suggestions.value=[];if(!text||text.length>60)return;timer=setTimeout(async()=>{try{const data=await listeningRequest('/api/content/suggest?q='+encodeURIComponent(text));if(version===suggestVersion)suggestions.value=data.records}catch{}},250)}
function chooseSuggestion(title:string){query.value=title;search()}
function setSort(value:string){sort.value=value;search()}
function setPay(value:string){payType.value=value;search()}
function previous(){page.value--;load()}function next(){page.value++;load()}
function open(id:number){uni.navigateTo({url:'/pages/detail/detail?id='+id})}
function home(){uni.navigateTo({url:'/pages/index/index'})}
onUnmounted(()=>{if(timer)clearTimeout(timer);suggestVersion++;loadVersion++});
onLoad((options:any)=>{query.value=options.q?decodeURIComponent(options.q):'';category.value=Number(options.category3Id)||0;categoryName.value=options.pageTitle?decodeURIComponent(options.pageTitle):'';load()});
</script><style scoped>.page{padding:30rpx;background:#f3f5ef;min-height:100vh;max-width:850px;margin:auto}.title{display:block;font-size:38rpx;font-weight:bold;margin:24rpx 0}.search{display:flex;gap:20rpx;align-items:center}.search input{flex:1;background:white;padding:24rpx;border-radius:16rpx}button{background:#244f45;color:white;font-size:26rpx}.hint{display:block;line-height:1.8;color:#708679;font-size:25rpx;margin:20rpx 0}.book{display:flex;gap:24rpx;background:white;border-radius:18rpx;padding:24rpx;margin:20rpx 0;cursor:pointer}.book image{width:150rpx;height:150rpx;flex-shrink:0;border-radius:12rpx}.name{font-size:29rpx;font-weight:bold}.pager{display:flex;gap:30rpx;margin:30rpx 0}.pager button{flex:1}.secondary{background:#e4ebe2;color:#244f45}.page{background:#f8f8f2;padding:32px 28px 100px;max-width:1060px}.title{font-size:27px}.search input{font-size:14px;border:1px solid #dce4d3;padding:15px}.search button,.pager button,.secondary{font-size:13px;border-radius:10px;padding:10px 20px;line-height:1.8}.hint{font-size:12px;color:#8a977e}.book{border:1px solid #e0e6d8;padding:20px;border-radius:16px;gap:22px}.book image{width:90px;height:90px;border-radius:12px}.name{font-size:16px;line-height:1.7;font-weight:500}@media(max-width:600px){.page{padding:24px 18px 90px}.title{font-size:23px}.search{gap:10px}.search input{font-size:12px;padding:12px}.search button{padding:9px 14px}.book{padding:16px;gap:14px}.book image{width:74px;height:74px}.name{font-size:13px}.hint{font-size:11px}.pager{gap:12px}}.filters{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;margin:20px 0}.filters>view{display:flex;gap:6px;flex-wrap:wrap}.filters button{margin:0;background:#e8eee2;color:#68765c;font-size:12px;padding:5px 12px;line-height:1.8}.filters button.active{background:#244f45;color:white}.match{color:#24785c;font-weight:700}.suggestions{background:white;border:1px solid #dce4d3;border-radius:12px;margin-top:8px}.suggestions>view{padding:12px 16px;cursor:pointer;border-bottom:1px solid #f0f2ec}.suggestions>view:last-child{border-bottom:0}</style>
